<script setup lang="ts">
import {ref,watch} from 'vue'
import {mutate,PLANNING_PREVIEW_TIMEOUT_MS} from '../api'
import type {BudgetSummary,EnginePreview} from '../explorationApi'
import {yuanToFen} from '../money'
import PlanPreview from './PlanPreview.vue'
const props=defineProps<{tripId:string;version:number;requirements?:Record<string,unknown>;budget:BudgetSummary}>()
const emit=defineEmits<{saved:[]}>()
const checked=ref<string[]>([]),amount=ref(''),busy=ref(false),error=ref(''),preview=ref<EnginePreview|null>(null),selected=ref(0)
watch(()=>[props.tripId,props.version,props.budget],()=>{checked.value=[];amount.value='';preview.value=null;error.value=''})
async function calculate(){if(busy.value||!props.requirements)return;busy.value=true;error.value='';try{const fen=yuanToFen(amount.value);if(fen===null||!checked.value.length)throw new Error('请填写累计已支付金额，并勾选该金额完整覆盖的费用项');const req=JSON.parse(JSON.stringify(props.requirements));const pricing={...(req.pricing as Record<string,unknown>),spending:{amount_fen:fen,as_of:new Date().toISOString(),covered_cost_ids:checked.value}};const result=await mutate<EnginePreview>(`/city/v1/trips/${props.tripId}/engine/replan-preview`,{expected_version:props.version,requirements:{...req,pricing},scope:'current_day'},'POST',PLANNING_PREVIEW_TIMEOUT_MS);if(!result.candidate_id)throw new Error(result.issues?.map(i=>i.message).join('；')||'尚未生成可确认的方案，请核对位置、进度及费用');preview.value=result;selected.value=0}catch(e){error.value=(e as Error).message}finally{busy.value=false}}
async function confirm(){if(!preview.value||busy.value)return;busy.value=true;error.value='';try{await mutate(`/city/v1/trips/${props.tripId}/engine/confirm`,{expected_version:preview.value.base_version,candidate_id:preview.value.candidate_id,alternative_index:selected.value});preview.value=null;emit('saved')}catch(e){error.value=(e as Error).message}finally{busy.value=false}}
</script>
<template><details v-if="requirements" class="budget-spending"><summary>记录已支付费用，重算今天剩余安排</summary><p>填写累计已支付金额，勾选该金额完整覆盖的项目（含预付住宿）。部分支付请暂不勾选整项；餐费预留仅在当天全部餐费已覆盖时勾选。请先核对当前位置及进度。</p><form @submit.prevent="calculate"><fieldset :disabled="busy"><label>累计已支付（元）<input v-model="amount" inputmode="decimal" required @input="preview=null"></label><label v-for="item in budget.items.filter(i=>i.category!=='spent'&&(!i.cost_id.startsWith('transport:')&&!i.cost_id.startsWith('tolls:')||i.day&&i.day<=new Date().toLocaleDateString('en-CA',{timeZone:'Asia/Shanghai'})))" :key="item.cost_id"><input v-model="checked" type="checkbox" :value="item.cost_id" @change="preview=null">{{item.day}} · {{item.label}}</label><label v-for="(id,index) in budget.items.find(i=>i.category==='spent')?.covered_cost_ids||[]" :key="id"><input v-model="checked" type="checkbox" :value="id" @change="preview=null">此前已覆盖：{{budget.items.find(i=>i.category==='spent')?.notes[index]||'已支付条目'}}</label><button type="submit">预览费用与今天剩余安排</button></fieldset></form><p v-if="error" role="alert">{{error}}</p><template v-if="preview"><PlanPreview :plans="preview.result.itineraries" :selected="selected" :disabled="busy" @select="selected=$event"/><button type="button" :disabled="busy" @click="confirm">确认更新费用与今天剩余安排</button></template></details></template>
<style scoped>.budget-spending{padding:14px;border:1px solid #ded4c2;border-radius:10px;margin-bottom:16px;font-size:13px;line-height:1.7}.budget-spending summary{min-height:40px;cursor:pointer}.budget-spending fieldset{border:0;padding:0;display:grid;gap:10px}.budget-spending label{display:block}.budget-spending input:not([type=checkbox]){display:block;min-height:44px;max-width:100%;box-sizing:border-box}.budget-spending button{min-height:44px;padding:10px;background:#345944;color:#fffaf1;border-radius:6px}</style>
